function wire(){
 A("[data-open]",b=>b.onclick=()=>{openB=b.dataset.open;show()});
 const bk=$("#bk");if(bk)bk.onclick=()=>{openB=null;show()};
 const nb=$("#nb");if(nb)nb.onsubmit=async e=>{e.preventDefault();const f=new FormData(nb);const {data,error}=await sb.from("batches").insert({name:f.get("name"),ship_date:f.get("d"),fx:FX}).select().single();if(error)return fail(error);openB=data.id;show()};
 const bs=$("#bs");if(bs)bs.onsubmit=async e=>{e.preventDefault();const f=new FormData(bs),o={};["fx","hold_pct","pct","round_to"].forEach(k=>o[k]=num(f.get(k)));o.ship_cost_ngn=cur=="USD"?num(f.get("ship_cost_ngn"))*o.fx:num(f.get("ship_cost_ngn"));o.split=f.get("split");o.mode=f.get("mode");
  const {error}=await sb.from("batches").update(o).eq("id",openB);if(error)return fail(error);show()};
 const sh=$("#shipb");if(sh)sh.onclick=async()=>{if(!confirm("Mark this batch as shipped? Costs will lock."))return;const {error}=await sb.rpc("ship_batch",{b:openB});if(error)return fail(error);show()};
 const af=$("#af");if(af)af.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(af));
  const row={name:f.name.trim(),category:f.category,gender:f.gender,colour:f.colour,brand:f.brand.trim(),size:f.size.trim(),condition:f.condition,qty:+f.qty};
  if(sup()){row.batch_id=f.batch;row.price_usd=f.price?num(f.price):null}else Object.assign(row,{source:"local",status:"in_stock",stock:+f.qty,qty_received:+f.qty,received_at:new Date().toISOString(),received_by:me.id,price_ngn:num(f.price)});
  const {data,error}=await sb.from("items").insert(row).select().single();if(error)return fail(error);
  const c=sup()?{cost_usd:num(f.cost),other_usd:num(f.other),entry_cur:"USD",entry_amt:num(f.cost)}:{other_ng:num(f.ngn),landed_ngn:num(f.ngn),entry_cur:"NGN",entry_amt:num(f.ngn)};
  const r2=await sb.from("item_costs").insert({item_id:data.id,...c});if(r2.error)return fail(r2.error);
  await show();app.insertAdjacentHTML("afterbegin",`<div class="card">✓ Saved <span class="sku">${esc(data.sku)}</span></div>`)};
 A("[data-disc]",b=>b.onclick=async()=>{const d=b.dataset,v=prompt(`Discount % for ${d.n} (0 removes it, max 90). Now: ${d.d}%`,+d.d>0?d.d:"15");if(v===null)return;const p=num(v);if(p>90)return alert("Maximum is 90%.");
  const np=Math.round(d.p*(1-p/100));if(p>0&&+d.l>0&&np<+d.l&&!confirm(`At ${ngn(np)} this sells below its cost of ${ngn(d.l)}. Continue?`))return;
  const note=p>0?(prompt("Reason (shown in reports)","Aged stock")||""):"";const {error}=await sb.rpc("set_discount",{i:d.disc,pct:p,note});if(error)return fail(error);show()});
 const rf=$("#rf");if(rf)rf.onsubmit=async e=>{e.preventDefault();const f=new FormData(rf);const {error}=await sb.from("settings").upsert([{key:"fx_mode",value:f.get("mode")},{key:"fx_manual",value:String(num(f.get("manual"))||1500)},{key:"fx_buffer",value:String(+f.get("buffer")||0)}]);if(error)return fail(error);await loadFx();chrome();show()};
 const fn=$("#fxnow");if(fn)fn.onclick=async()=>{fn.disabled=true;await refreshFx(true);show()};
 const qi=$("#q");if(qi)qi.oninput=()=>{q=qi.value;const p=qi.selectionStart;show().then(()=>{const n=$("#q");n.focus();n.setSelectionRange(p,p)})};
 A("[data-rc]",b=>b.onclick=async()=>{const {error}=await sb.rpc("confirm_receipt",{i:b.dataset.rc,got:parseInt($("#r"+b.dataset.rc).value)||0});if(error)return fail(error);show()});
 const ps=$("#ps");if(ps){ps.oninput=renderResults;renderResults()}
 app.onclick=e=>{const d=e.target.dataset;if(d.add){const i=window._st.find(x=>x.id==d.add),l=cart.find(x=>x.item_id==i.id);if(l)l.qty=Math.min(l.max,l.qty+1);else{if(!sup()&&!i.price_ngn)return alert("Price not set yet. Ask the owner.");const e0=eff(i);cart.push({item_id:i.id,sku:i.sku,name:i.name,qty:1,max:i.stock,price:e0,min:e0,list:+i.price_ngn||0})}show()}
  if(d.cx){cart.splice(+d.cx,1);show()}};
 A("[data-cq]",i=>i.onchange=()=>{cart[+i.dataset.cq].qty=Math.max(1,Math.min(cart[+i.dataset.cq].max,parseInt(i.value)||1));show()});
 A("[data-cp]",i=>i.onchange=()=>{const l=cart[+i.dataset.cp],v=num(i.value);if(!sup()&&v<l.min){alert("Staff cannot sell below the authorised price of "+ngn(l.min));l.price=l.min}else l.price=v;show()});
 const pe=$("#per");if(pe)pe.onchange=()=>{per=+pe.value;show()};
 const co=$("#co");if(co)co.onclick=async()=>{co.disabled=true;const cust=$("#cu").value.trim(),pay=$("#pm").value,ls=cart.slice();
  const {data,error}=await sb.rpc("sell",{cust,pay,lines:ls.map(l=>({item_id:l.item_id,qty:l.qty,price:l.price}))});if(error){co.disabled=false;return fail(error)}cart=[];
  const r={no:data,at:new Date().toISOString(),cashier:me.name||me.email,customer:cust,pay,lines:ls.map(l=>({sku:l.sku,name:l.name,qty:l.qty,price:l.price,list:l.list})),total:ls.reduce((a,l)=>a+l.qty*l.price,0)};
  showReceipt(r);if(localStorage.getItem("rw_ap")=="1")printRcpt(r)};
 const ap=$("#ap");if(ap)ap.onchange=()=>localStorage.setItem("rw_ap",ap.checked?"1":"0");
 A("[data-rp]",b=>b.onclick=async()=>{const x=window._rs.find(y=>y.id==b.dataset.rp),{data:ls,error}=await sb.from("sale_lines").select("sku,name,qty,unit_price,list_price").eq("sale_id",x.id);if(error)return fail(error);
  showReceipt({no:x.receipt,at:x.sold_at,cashier:x.cashier||"—",customer:x.customer||"",pay:x.payment,reprint:true,lines:ls.map(l=>({sku:l.sku,name:l.name,qty:l.qty,price:l.unit_price,list:l.list_price})),total:x.total})});
 const bg=$("#bk-go");if(bg)bg.onclick=doExport;
 const bd=$("#bk-d");if(bd)bd.onchange=async()=>{const {error}=await sb.from("settings").upsert({key:"backup_days",value:bd.value});if(error)return fail(error);await loadBk()};
 const t0=$("#imp-tpl");if(t0)t0.onclick=doTemplate;
 const ifl=$("#imp-file");if(ifl)ifl.onchange=()=>{if(ifl.files[0])parseImport(ifl.files[0])};
 A("[data-un]",i=>i.onchange=async()=>{const {error}=await sb.from("profiles").update({name:i.value.trim()}).eq("id",i.dataset.un);if(error)fail(error)});
 A("[data-ur]",s=>s.onchange=async()=>{const {error}=await sb.from("profiles").update({role:s.value}).eq("id",s.dataset.ur);if(error)fail(error)});
 A("[data-ua]",s=>s.onchange=async()=>{const {error}=await sb.from("profiles").update({active:s.checked}).eq("id",s.dataset.ua);if(error)fail(error)})}
boot();

const eqUpdate=f=>{if(!f||f.id!="af"||!sup()||!f.elements.batch||!$("#eq"))return;const g=n=>num(f.elements[n]?.value),o=f.elements.batch.selectedOptions[0];
 if(!o){$("#eq").textContent="Create an open batch first (Batches tab).";return}
 const bfx=+o.dataset.fx||FX,pct=+o.dataset.pct||0,mg=o.dataset.mode=="margin",n0=x=>"₦"+Math.round(x).toLocaleString("en-NG"),u=x=>"$"+x.toFixed(2),c=g("cost")+g("other"),p=g("price"),sug=c?(mg?c/(1-Math.min(pct,99)/100):c*(1+pct/100)):0;
 let h="";if(c)h+=`Cost ≈ ${n0(c*bfx)} at the batch rate ₦${Math.round(bfx)}/$. Starting price at this batch's ${pct}% ${mg?"margin":"markup"}: ${u(sug)} ≈ ${n0(Math.ceil(sug*FX/500)*500)} (before shipping and holding costs).`;
 if(p)h+=` Your price ${u(p)} ≈ <b>${n0(Math.ceil(p*FX/500)*500)}</b> at today's rate ₦${Math.round(FX)}/$${FXR?` (7-day range ${n0(p*FXR[0])} – ${n0(p*FXR[1])})`:""}. This naira price appears in Stock once staff confirm receipt in Kaduna.`;
 $("#eq").innerHTML=h};
document.addEventListener("input",e=>{eqUpdate(e.target.form);const t=e.target.id;if(t=="cv-u")$("#cv-n").value=Math.round(num(e.target.value)*FX);if(t=="cv-n")$("#cv-u").value=(num(e.target.value)/FX).toFixed(2)});
document.addEventListener("change",e=>eqUpdate(e.target.form));
